import React, {useState, useEffect} from 'react';
import {useParams, useNavigate} from 'react-router-dom';
import axios from 'axios';
import {toast} from 'sonner';
import useAuthStore from '@/store/authStore';
import { BASE_URL as API } from '@/services/api';
import {useLanguage} from '@/context/LanguageContext';
import Layout from '@/components/Layout';
import {Button} from '@/components/ui/button';
import {Card} from '@/components/ui/card';
import {Input} from '@/components/ui/input';
import {Textarea} from '@/components/ui/textarea';
import {Dialog, DialogContent, DialogHeader, DialogTitle} from '@/components/ui/dialog';
import {Label} from '@/components/ui/label';
import {Calendar, MapPin, DollarSign, FileText, Banknote, Download} from 'lucide-react';
import StaticLayout from "@/components/StaticLayout";

const styles = `
  .tender-detail-protocol-icon {
    margin-right: var(--space-2);
  }
  .tender-detail-doc-span {
    flex: 1;
  }
  .tender-detail-archive-card {
    padding: var(--space-8);
    text-align: center;
    background: linear-gradient(135deg, var(--color-bg-muted) 0%, var(--color-border) 100%);
    border: 1px solid var(--color-border-gray);
  }
  .tender-detail-archive-inner {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: var(--space-3);
  }
  .tender-detail-archive-icon {
    color: var(--color-text-placeholder);
  }
  .tender-detail-archive-title {
    font-size: var(--font-size-3xl);
    font-weight: var(--font-weight-bold);
    color: var(--color-text-muted);
    margin: 0;
  }
  .tender-detail-archive-text {
    color: var(--color-text-placeholder);
    margin: 0;
    font-size: var(--font-size-base);
  }
`;


const TenderDetail = () => {
    const {id} = useParams();
    const navigate = useNavigate();
    const user = useAuthStore(s => s.user);
    const {t, language} = useLanguage();
    const [tender, setTender] = useState(null);
    const [bids, setBids] = useState([]);
    const [showBidDialog, setShowBidDialog] = useState(false);
    const [loading, setLoading] = useState(true);
    const [submittingBid, setSubmittingBid] = useState(false);
    const [agreeToTerms, setAgreeToTerms] = useState(false);
    const [attachedFiles, setAttachedFiles] = useState([]);
    const [bidForm, setBidForm] = useState({
        price: '',
        proposal: '',
        delivery_time: '',
        documents: []
    });

    useEffect(() => {
        fetchTenderDetails();
    }, [id]);
    const fetchTenderDetails = async () => {
        try {
            const tenderResponse = await axios.get(`${API}/tenders/${id}`);
            setTender(tenderResponse.data);

            if (user && user.role === 'customer' && tenderResponse.data.customer_id === user.id) {
                const bidsResponse = await axios.get(`${API}/bids/tender/${id}`);
                setBids(bidsResponse.data);
            }
        } catch (error) {
            toast.error(t('common.error'));
            navigate('/tenders');
        } finally {
            setLoading(false);
        }
    };

    const getLocalizedField = (item, field) => {
        if (!item) return '';
        if (language === 'ru') return item[field] || '';
        return item[`${field}_${language}`] || item[field] || '';
    };

    const handleFileUpload = async (event) => {
        const files = Array.from(event.target.files);
        const uploadedFiles = [];

        for (const file of files) {
            if (file.size > 10 * 1024 * 1024) { // 10MB limit
                toast.error(`${file.name} ${t('tenderDetail.fileExceedsLimit')}`);
                continue;
            }

            const base64 = await convertToBase64(file);
            uploadedFiles.push({
                filename: file.name,
                content: base64,
                type: file.type,
                size: file.size.toString()
            });
        }

        setAttachedFiles([...attachedFiles, ...uploadedFiles]);
    };
    const linkStyle = {
        display: 'flex',
        alignItems: 'center',
        gap: 'var(--space-2-5)',
        padding: 'var(--space-2-5) var(--space-3-5)',
        border: '0.5px solid var(--color-border)',
        borderRadius: 'var(--radius-lg)',
        textDecoration: 'none',
        color: 'var(--color-text-dark)',
        background: 'var(--color-bg-warm-secondary)',
        fontSize: 'var(--font-size-base)'
    };

    const iconStyle = {
        color: 'var(--color-text-secondary)',
        flexShrink: 0
    };
    const convertToBase64 = (file) => {
        return new Promise((resolve, reject) => {
            const fileReader = new FileReader();
            fileReader.readAsDataURL(file);
            fileReader.onload = () => resolve(fileReader.result);
            fileReader.onerror = (error) => reject(error);
        });
    };

    const removeFile = (index) => {
        const newFiles = attachedFiles.filter((_, i) => i !== index);
        setAttachedFiles(newFiles);
    };

    const handleSubmitBid = async (e) => {
        e.preventDefault();

        // Validation
        if (!agreeToTerms) {
            toast.error(t('tenderDetail.agreeToTermsRequired'));
            return;
        }

        const bidPrice = parseFloat(bidForm.price);

        if (!bidForm.price || bidPrice <= 0) {
            toast.error(t('tenderDetail.invalidPrice'));
            return;
        }

        // Check if bid price exceeds tender budget
        if (bidPrice > tender.budget) {
            toast.error(t('tenderDetail.priceExceedsBudget'));
            return;
        }

        if (!bidForm.delivery_time || parseInt(bidForm.delivery_time) <= 0) {
            toast.error(t('tenderDetail.deliveryTimeRequired'));
            return;
        }

        if (!bidForm.proposal || bidForm.proposal.length < 50) {
            toast.error(t('tenderDetail.proposalTooShort'));
            return;
        }

        // Check if tender is still accepting bids
        const now = new Date();
        if (tender.deadline) {
            const deadline = new Date(tender.deadline);
            if (now > deadline) {
                toast.error(t('tenderDetail.deadlinePassed'));
                return;
            }
        }

        setSubmittingBid(true);

        try {
            const token = localStorage.getItem('token');
            await axios.post(
                `${API}/bids`,
                {
                    tender_id: id,
                    price: bidPrice,
                    proposal: bidForm.proposal,
                    delivery_time: bidForm.delivery_time,
                    documents: attachedFiles
                },
                {
                    headers: {
                        'Authorization': `Bearer ${token}`
                    }
                }
            );

            toast.success(t('tenderDetail.bidSubmitSuccess'));
            setShowBidDialog(false);
            setBidForm({price: '', proposal: '', delivery_time: ''});
            setAttachedFiles([]);
            setAgreeToTerms(false);

            // Refresh tender details to show updated info
            fetchTenderDetails();
        } catch (error) {
            const errorMsg = error.response?.data?.detail || t('tenderDetail.bidSubmitError');
            toast.error(errorMsg);
        } finally {
            setSubmittingBid(false);
        }
    };

    const handleSelectWinner = async () => {
        try {
            await axios.post(`${API}/bids/${id}/select-winner`);
            toast.success(t('common.success'));
            fetchTenderDetails();
        } catch (error) {
            toast.error(error.response?.data?.detail || t('common.error'));
        }
    };
    console.log(tender)

    if (loading) {
        return (
            <Layout>
                <div className="loading-container">
                    <div className="loading-spinner"></div>
                </div>
            </Layout>
        );
    }

    if (!tender) return null;

    const isOwner = user && user.role === 'customer' && tender.customer_id === user.id;
    const canBid = user && user.role === 'contractor' &&
        (tender.status === 'active' || tender.status === 'published_receiving_proposals' || tender.status === 'published');


    const getStatusLabel = (status) => t(`status.${status}`);
    const getTypeLabel = (type) => {
        if (!type) return '';
        const map = {
            price_proposals: t('tenderList.priceProposals'),
            open_competition: t('tenderList.openCompetition'),
            auction: t('tenderList.auction'),
            single_source: t('tenderList.singleSource'),
        };
        return map[type] || type.replace('_', ' ');
    };
    console.log(tender)
    const getCategoryLabel = (category) => {
        const map = {
            construction: t('tenderList.construction'),
            it: t('tenderList.itServices'),
            consulting: t('tenderList.consulting'),
            logistics: t('tenderList.logistics'),
        };
        return map[category] || category;
    };
    if (user) {
        return (
            <Layout>
                <style>{styles}</style>
                <div className="tender-detail-container" data-testid="tender-detail">
                    <div className="tender-header-section">
                        <div>
                            <h1 className="tender-title"
                                data-testid="tender-title">{getLocalizedField(tender, 'title')}</h1>
                            <div className="tender-meta">
              <span className={`status-badge status-${tender.status}`}>
                {getStatusLabel(tender.status)}
              </span>
                                <span className="tender-type">{getTypeLabel(tender.tender_type)}</span>
                            </div>
                        </div>
                        {canBid && (
                            <Button
                                onClick={() => navigate(`/tenders/${tender.id}/submit-bid`)}
                                className="neon-button-filled"
                                data-testid="submit-bid-btn"
                            >
                                {t('tenderDetail.submitBid')}
                            </Button>
                        )}
                        {isOwner && tender.status === 'active' && bids.filter(b => b.status === 'stage1_approved').length > 0 && (
                            <Button
                                onClick={handleSelectWinner}
                                className="neon-button-filled"
                                data-testid="select-winner-btn"
                            >
                                {t('tenderDetail.selectWinner')}
                            </Button>
                        )}
                        {/* Показать протокол для закрытых и завершенных тендеров */}
                        {(tender.status === 'closed' || tender.status === 'failed') && (
                            <Button
                                onClick={() => navigate(`/protocol/${id}`)}
                                className="neon-button-filled"
                                data-testid="view-protocol-btn"
                            >
                                <FileText size={16} className="tender-detail-protocol-icon"/>
                                {t('tenderDetail.viewProtocol')}
                            </Button>
                        )}
                    </div>

                    <div className="tender-content">
                        <Card className="tender-info-card neon-card">
                            <h2 className="section-title">{t('tenderDetail.tenderInfo')}</h2>

                            <div className="info-grid">
                                <div className="info-item">
                                    <Banknote className="info-icon"/>
                                    <div>
                                        <p className="info-label">{t('tenderList.budget')}</p>
                                        <p className="info-value">{tender.budget.toLocaleString()} {tender.id === '508e1745-94d6-40ca-9bd5-1e09327ad4f8' ? `$` : '₸'}</p>
                                    </div>
                                </div>

                                <div className="info-item">
                                    <Calendar className="info-icon"/>
                                    <div>
                                        <p className="info-label">{t('tenderDetail.deadline')}</p>
                                        <p className="info-value">{new Date(tender.deadline).toLocaleDateString()}</p>
                                    </div>
                                </div>

                                <div className="info-item">
                                    <MapPin className="info-icon"/>
                                    <div>
                                        <p className="info-label">{t('tenderList.region')}</p>
                                        <p className="info-value">{tender.region}</p>
                                    </div>
                                </div>

                                <div className="info-item">
                                    <FileText className="info-icon"/>
                                    <div>
                                        <p className="info-label">{t('tenderList.category')}</p>
                                        <p className="info-value">{getCategoryLabel(tender.category)}</p>
                                    </div>
                                </div>
                            </div>
                            <div className="description-section">
                                <h3 className="subsection-title">{t('tenderDetail.description')}</h3>
                                <p className="description-text">{getLocalizedField(tender, 'description')}</p>
                            </div>

                            <div className="description-section">
                                <h3 className="subsection-title">{t('tenderDetail.technicalSpecs')}</h3>
                                <p className="description-text">{getLocalizedField(tender, 'technical_specs')}</p>
                            </div>
                            {String(tender?.id).toLowerCase() === '508e1745-94d6-40ca-9bd5-1e09327ad4f8' ? (
                                    <div className="description-section">
                                        <h3 className="subsection-title">{t('tenderDetail.documents')}</h3>
                                        <div style={{
                                            display: 'flex',
                                            flexDirection: 'column',
                                            gap: '10px',
                                            marginTop: '8px'
                                        }}>
                                            {[
                                                {name: t('tenderDetail.document1'), url: '/documents/tz.pdf'},
                                                {
                                                    name: t('tenderDetail.document2'),
                                                    url: '/documents/tender_announcement.pdf'
                                                },
                                                {name: t('tenderDetail.document3'), url: '/documents/press.pdf'},
                                                {name: t('tenderDetail.document4'), url: '/documents/agreement.pdf'},
                                            ].map((doc, idx) => (
                                                <a key={idx} href={doc.url} download style={linkStyle}>
                                                    <FileText size={16} style={iconStyle}/><span
                                                    className="tender-detail-doc-span">{doc.name}</span><Download size={15}
                                                                                                                  style={iconStyle}/>
                                                </a>
                                            ))}
                                        </div>
                                    </div>
                                ) : /* Условие для НОВОГО тендера */
                                String(tender?.id).toLowerCase() === 'd7e8f9a0-b1c2-3d4e-5f6a-7b8c9d0e1f2a' ? (
                                    <div className="description-section">
                                        <h3 className="subsection-title">{t('tenderDetail.documents')}</h3>
                                        <div style={{
                                            display: 'flex',
                                            flexDirection: 'column',
                                            gap: '10px',
                                            marginTop: '8px'
                                        }}>
                                            {[
                                                {name: "Техническое задание (TEP)", url: '/documents/tep_tz.pdf'},
                                                {name: "Объявление о закупке (TEP)", url: '/documents/tep_anounce.pdf'},
                                            ].map((doc, idx) => (
                                                <a key={idx} href={doc.url} download style={linkStyle}>
                                                    <FileText size={16} style={iconStyle}/><span
                                                    className="tender-detail-doc-span">{doc.name}</span><Download
                                                    size={15}
                                                    style={iconStyle}/>
                                                </a>
                                            ))}
                                        </div>
                                    </div>
                                ) : ['a1b2c3d4-e5f6-7890-abcd-ef1234567890', 'f29a7d3e-8b1c-4b92-a165-92d3f4b5c6e7'].includes(String(tender?.id).toLowerCase()) ? (
                                    <div className="description-section">
                                        <h3 className="subsection-title">{t('tenderDetail.documents')}</h3>
                                        <div style={{
                                            display: 'flex',
                                            flexDirection: 'column',
                                            gap: '10px',
                                            marginTop: '8px'
                                        }}>
                                            {[
                                                {
                                                    name: 'EPCM — Контракт (T1)',
                                                    url: '/documents/q-30-T1_EPCM_Pro_v4.pdf'
                                                },
                                                {
                                                    name: 'Техническое задание (T2)',
                                                    url: '/documents/q-30-T2_TZ_Pro_v4.pdf'
                                                },
                                                {
                                                    name: 'Комитет — Решение (T4)',
                                                    url: '/documents/q-30-T4_Committee_v4.pdf'
                                                },
                                                {name: 'Состав комитета', url: '/documents/q-30-comitee.pdf'},
                                                {
                                                    name: 'Тендерная презентация Q-30',
                                                    url: '/documents/q-30-tender_presentation_q30_v3.pdf'
                                                },
                                            ].map((doc, idx) => (
                                                <a
                                                    key={idx}
                                                    href={doc.url}
                                                    download
                                                    style={linkStyle}
                                                >
                                                    <FileText size={16} style={iconStyle}/>
                                                    <span className="tender-detail-doc-span">{doc.name}</span>
                                                    <Download size={15} style={iconStyle}/>
                                                </a>
                                            ))}
                                        </div>
                                    </div>
                                ) : (
                                    /* Все остальные тендеры */
                                    (tender?.documents && tender.documents.length > 0) ? (
                                        <div className="description-section">
                                            <h3 className="subsection-title">{t('tenderDetail.documents')}</h3>
                                            <div style={{
                                                display: 'flex',
                                                flexDirection: 'column',
                                                gap: '10px',
                                                marginTop: '8px'
                                            }}>
                                                {tender.documents.map((doc, index) => (
                                                    <a key={index} href={doc.url} download style={linkStyle}>
                                                        <FileText size={16} style={iconStyle}/><span
                                                        className="tender-detail-doc-span">{doc.name || `${t('tenderDetail.documentFallback')} ${index + 1}`}</span><Download
                                                        size={15} style={iconStyle}/>
                                                    </a>
                                                ))}
                                            </div>
                                        </div>
                                    ) : null
                                )}
                            {tender.requirements && tender.requirements.length > 0 && (
                                <div className="description-section">
                                    <h3 className="subsection-title">{t('tenderDetail.requirements')}</h3>
                                    <ul className="requirements-list">
                                        {tender.requirements.map((req, idx) => (
                                            <li key={idx}>{req}</li>
                                        ))}
                                    </ul>
                                </div>
                            )}

                            {tender.evaluation_criteria && (tender.evaluation_criteria.technical || tender.evaluation_criteria.financial) && (
                                <div className="description-section">
                                    <h3 className="subsection-title">{t('tenderDetail.evaluationCriteria')}</h3>
                                    <div style={{
                                        display: 'flex',
                                        flexDirection: 'column',
                                        gap: '16px',
                                        marginTop: '12px'
                                    }}>
                                        {tender.evaluation_criteria.technical && (
                                            <div className="criteria-block">
                                                <div className="criteria-block-header">
                                                    <span
                                                        className="criteria-block-title">{t('tenderDetail.technicalCriteria')}</span>
                                                    <span
                                                        className="criteria-total-weight">{tender.evaluation_criteria.technical.weight_pct}%</span>
                                                </div>
                                                {tender.evaluation_criteria.technical.subcriteria && tender.evaluation_criteria.technical.subcriteria.length > 0 && (
                                                    <div className="criteria-subcriteria">
                                                        {tender.evaluation_criteria.technical.subcriteria.map((sub, idx) => (
                                                            <div key={idx} className="criteria-row">
                                                                <span
                                                                    className="criteria-name">{getLocalizedField(sub, 'name')}</span>
                                                                <div className="criteria-weight-bar">
                                                                    <div
                                                                        className="criteria-bar-fill criteria-bar-technical"
                                                                        style={{width: `${(sub.weight_pct / tender.evaluation_criteria.technical.weight_pct) * 100}%`}}/>
                                                                </div>
                                                                <span
                                                                    className="criteria-weight-label">{sub.weight_pct}%</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        )}
                                        {tender.evaluation_criteria.financial && (
                                            <div className="criteria-block">
                                                <div className="criteria-block-header">
                                                    <span
                                                        className="criteria-block-title">{t('tenderDetail.financialCriteria')}</span>
                                                    <span
                                                        className="criteria-total-weight">{tender.evaluation_criteria.financial.weight_pct}%</span>
                                                </div>
                                                {tender.evaluation_criteria.financial.subcriteria && tender.evaluation_criteria.financial.subcriteria.length > 0 && (
                                                    <div className="criteria-subcriteria">
                                                        {tender.evaluation_criteria.financial.subcriteria.map((sub, idx) => (
                                                            <div key={idx} className="criteria-row">
                                                                <span
                                                                    className="criteria-name">{getLocalizedField(sub, 'name')}</span>
                                                                <div className="criteria-weight-bar">
                                                                    <div
                                                                        className="criteria-bar-fill criteria-bar-financial"
                                                                        style={{width: `${(sub.weight_pct / tender.evaluation_criteria.financial.weight_pct) * 100}%`}}/>
                                                                </div>
                                                                <span
                                                                    className="criteria-weight-label">{sub.weight_pct}%</span>
                                                            </div>
                                                        ))}
                                                    </div>
                                                )}
                                            </div>
                                        )}
                                    </div>
                                </div>
                            )}
                        </Card>

                        {isOwner && bids.length > 0 && (
                            <Card className="bids-card neon-card">
                                <h2 className="section-title">{t('tenderDetail.submittedBids')} ({bids.length})</h2>
                                <div className="bids-list">
                                    {bids.map((bid) => (
                                        <div key={bid.id} className="bid-item" data-testid={`bid-${bid.id}`}>
                                            <div className="bid-header">
                                                <div>
                                                    <p className="bid-contractor">{bid.contractor_email}</p>
                                                    <p className="bid-price">{bid.price.toLocaleString()} {tender.id === '508e1745-94d6-40ca-9bd5-1e09327ad4f8' ? `$` : '₸'}</p>
                                                </div>
                                                <div className="bid-status-info">
                        <span className={`status-badge status-${bid.status}`}>
                          {getStatusLabel(bid.status)}
                        </span>
                                                    <span
                                                        className="bid-score">{t('tenderDetail.aiScore')}: {bid.ai_score.toFixed(1)}/100</span>
                                                </div>
                                            </div>
                                            <p className="bid-proposal">{bid.proposal}</p>
                                            <p className="bid-delivery">{t('tenderDetail.delivery')}: {bid.delivery_time}</p>
                                        </div>
                                    ))}
                                </div>
                            </Card>
                        )}

                        {tender.status === 'archive' && tender.winner_id == null && (
                            <Card className="neon-card tender-detail-archive-card">
                                <div className="tender-detail-archive-inner">
                                    <FileText size={40} className="tender-detail-archive-icon"/>
                                    <h2 className="tender-detail-archive-title">
                                        {t('tenderDetail.archiveCancelled')}
                                    </h2>
                                </div>
                            </Card>
                        )}

                        {tender.status === 'archive' && tender.winner_id != null && (
                            <Card className="neon-card tender-detail-archive-card">
                                <div className="tender-detail-archive-inner">
                                    <FileText size={40} className="tender-detail-archive-icon"/>
                                    <h2 className="tender-detail-archive-title">
                                        {t('tenderDetail.archive')}
                                    </h2>
                                </div>
                            </Card>
                        )}

                        {tender.status === 'cancelled' && (
                            <Card className="neon-card tender-detail-archive-card">
                                <div className="tender-detail-archive-inner">
                                    <FileText size={40} className="tender-detail-archive-icon"/>
                                    <h2 className="tender-detail-archive-title">
                                        {t('status.cancelled')}
                                    </h2>
                                </div>
                            </Card>
                        )}
                    </div>
                </div>
            </Layout>
        )
    }
    return (
        <StaticLayout>
            <style>{styles}</style>
            <div className="tender-detail-container" data-testid="tender-detail">
                <div className="tender-header-section">
                    <div>
                        <h1 className="tender-title"
                            data-testid="tender-title">{getLocalizedField(tender, 'title')}</h1>
                        <div className="tender-meta">
              <span className={`status-badge status-${tender.status}`}>
                {getStatusLabel(tender.status)}
              </span>
                            <span className="tender-type">{getTypeLabel(tender.tender_type)}</span>
                        </div>
                    </div>
                    {canBid && (
                        <Button
                            onClick={() => navigate(`/tenders/${tender.id}/submit-bid`)}
                            className="neon-button-filled"
                            data-testid="submit-bid-btn"
                        >
                            {t('tenderDetail.submitBid')}
                        </Button>
                    )}
                    {isOwner && tender.status === 'active' && bids.filter(b => b.status === 'stage1_approved').length > 0 && (
                        <Button
                            onClick={handleSelectWinner}
                            className="neon-button-filled"
                            data-testid="select-winner-btn"
                        >
                            {t('tenderDetail.selectWinner')}
                        </Button>
                    )}
                    {/* Показать протокол для закрытых и завершенных тендеров */}
                    {(tender.status === 'closed' || tender.status === 'failed') && (
                        <Button
                            onClick={() => navigate(`/protocol/${id}`)}
                            className="neon-button-filled"
                            data-testid="view-protocol-btn"
                        >
                            <FileText size={16} className="tender-detail-protocol-icon"/>
                            {t('tenderDetail.viewProtocol')}
                        </Button>
                    )}
                </div>

                <div className="tender-content">
                    <Card className="tender-info-card neon-card">
                        <h2 className="section-title">{t('tenderDetail.tenderInfo')}</h2>

                        <div className="info-grid">
                            <div className="info-item">
                                <Banknote className="info-icon"/>
                                <div>
                                    <p className="info-label">{t('tenderList.budget')}</p>
                                    <p className="info-value">{tender.budget.toLocaleString()} {tender.id === '508e1745-94d6-40ca-9bd5-1e09327ad4f8' ? `$` : '₸'}</p>
                                </div>
                            </div>

                            <div className="info-item">
                                <Calendar className="info-icon"/>
                                <div>
                                    <p className="info-label">{t('tenderDetail.deadline')}</p>
                                    <p className="info-value">{new Date(tender.deadline).toLocaleDateString()}</p>
                                </div>
                            </div>

                            <div className="info-item">
                                <MapPin className="info-icon"/>
                                <div>
                                    <p className="info-label">{t('tenderList.region')}</p>
                                    <p className="info-value">{tender.region}</p>
                                </div>
                            </div>

                            <div className="info-item">
                                <FileText className="info-icon"/>
                                <div>
                                    <p className="info-label">{t('tenderList.category')}</p>
                                    <p className="info-value">{getCategoryLabel(tender.category)}</p>
                                </div>
                            </div>
                        </div>
                        <div className="description-section">
                            <h3 className="subsection-title">{t('tenderDetail.description')}</h3>
                            <p className="description-text">{getLocalizedField(tender, 'description')}</p>
                        </div>

                        <div className="description-section">
                            <h3 className="subsection-title">{t('tenderDetail.technicalSpecs')}</h3>
                            <p className="description-text">{getLocalizedField(tender, 'technical_specs')}</p>
                        </div>

                        {String(tender?.id).toLowerCase() === '508e1745-94d6-40ca-9bd5-1e09327ad4f8' ? (
                                <div className="description-section">
                                    <h3 className="subsection-title">{t('tenderDetail.documents')}</h3>
                                    <div style={{display: 'flex', flexDirection: 'column', gap: '10px', marginTop: '8px'}}>
                                        {[
                                            {name: t('tenderDetail.document1'), url: '/documents/tz.pdf'},
                                            {name: t('tenderDetail.document2'), url: '/documents/tender_announcement.pdf'},
                                            {name: t('tenderDetail.document3'), url: '/documents/press.pdf'},
                                            {name: t('tenderDetail.document4'), url: '/documents/agreement.pdf'},
                                        ].map((doc, idx) => (
                                            <a key={idx} href={doc.url} download style={linkStyle}>
                                                <FileText size={16} style={iconStyle}/><span
                                                className="tender-detail-doc-span">{doc.name}</span><Download size={15}
                                                                                                              style={iconStyle}/>
                                            </a>
                                        ))}
                                    </div>
                                </div>
                            ) : /* Условие для НОВОГО тендера */
                            String(tender?.id).toLowerCase() === 'd7e8f9a0-b1c2-3d4e-5f6a-7b8c9d0e1f2a' ? (
                                <div className="description-section">
                                    <h3 className="subsection-title">{t('tenderDetail.documents')}</h3>
                                    <div style={{
                                        display: 'flex',
                                        flexDirection: 'column',
                                        gap: '10px',
                                        marginTop: '8px'
                                    }}>
                                        {[
                                            {name: "Техническое задание (TEP)", url: '/documents/tep_tz.pdf'},
                                            {name: "Объявление о закупке (TEP)", url: '/documents/tep_anounce.pdf'},
                                        ].map((doc, idx) => (
                                            <a key={idx} href={doc.url} download style={linkStyle}>
                                                <FileText size={16} style={iconStyle}/><span
                                                className="tender-detail-doc-span">{doc.name}</span><Download size={15}
                                                                                                              style={iconStyle}/>
                                            </a>
                                        ))}
                                    </div>
                                </div>
                            ) : ['a1b2c3d4-e5f6-7890-abcd-ef1234567890', 'f29a7d3e-8b1c-4b92-a165-92d3f4b5c6e7'].includes(String(tender?.id).toLowerCase()) ? (
                                <div className="description-section">
                                    <h3 className="subsection-title">{t('tenderDetail.documents')}</h3>
                                    <div style={{
                                        display: 'flex',
                                        flexDirection: 'column',
                                        gap: '10px',
                                        marginTop: '8px'
                                    }}>
                                        {[
                                            {name: 'EPCM — Контракт (T1)', url: '/documents/q-30-T1_EPCM_Pro_v4.pdf'},
                                            {name: 'Техническое задание (T2)', url: '/documents/q-30-T2_TZ_Pro_v4.pdf'},
                                            {
                                                name: 'Комитет — Решение (T4)',
                                                url: '/documents/q-30-T4_Committee_v4.pdf'
                                            },
                                            {name: 'Состав комитета', url: '/documents/q-30-comitee.pdf'},
                                            {
                                                name: 'Тендерная презентация Q-30',
                                                url: '/documents/q-30-tender_presentation_q30_v3.pdf'
                                            },
                                        ].map((doc, idx) => (
                                            <div
                                                key={idx}
                                                onClick={() => {
                                                    const link = document.createElement('a');
                                                    link.href = doc.url;
                                                    link.download = doc.name + '.pdf';
                                                    document.body.appendChild(link);
                                                    link.click();
                                                    document.body.removeChild(link);
                                                }}
                                                style={{...linkStyle, cursor: 'pointer'}}
                                            >
                                                <FileText size={16} style={iconStyle}/>
                                                <span className="tender-detail-doc-span">{doc.name}</span>
                                                <Download size={15} style={iconStyle}/>
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            ) : (
                                /* Все остальные тендеры */
                                (tender?.documents && tender.documents.length > 0) ? (
                                    <div className="description-section">
                                        <h3 className="subsection-title">{t('tenderDetail.documents')}</h3>
                                        <div style={{
                                            display: 'flex',
                                            flexDirection: 'column',
                                            gap: '10px',
                                            marginTop: '8px'
                                        }}>
                                            {tender.documents.map((doc, index) => (
                                                <a key={index} href={doc.url} download style={linkStyle}>
                                                    <FileText size={16} style={iconStyle}/><span
                                                    className="tender-detail-doc-span">{doc.name || `${t('tenderDetail.documentFallback')} ${index + 1}`}</span><Download
                                                    size={15} style={iconStyle}/>
                                                </a>
                                            ))}
                                        </div>
                                    </div>
                                ) : null
                            )}
                        {tender.requirements && tender.requirements.length > 0 && (
                            <div className="description-section">
                                <h3 className="subsection-title">{t('tenderDetail.requirements')}</h3>
                                <ul className="requirements-list">
                                    {tender.requirements.map((req, idx) => (
                                        <li key={idx}>{req}</li>
                                    ))}
                                </ul>
                            </div>
                        )}

                        {tender.evaluation_criteria && (tender.evaluation_criteria.technical || tender.evaluation_criteria.financial) && (
                            <div className="description-section">
                                <h3 className="subsection-title">{t('tenderDetail.evaluationCriteria')}</h3>
                                <div style={{display: 'flex', flexDirection: 'column', gap: '16px', marginTop: '12px'}}>
                                    {tender.evaluation_criteria.technical && (
                                        <div className="criteria-block">
                                            <div className="criteria-block-header">
                                                <span
                                                    className="criteria-block-title">{t('tenderDetail.technicalCriteria')}</span>
                                                <span
                                                    className="criteria-total-weight">{tender.evaluation_criteria.technical.weight_pct}%</span>
                                            </div>
                                            {tender.evaluation_criteria.technical.subcriteria && tender.evaluation_criteria.technical.subcriteria.length > 0 && (
                                                <div className="criteria-subcriteria">
                                                    {tender.evaluation_criteria.technical.subcriteria.map((sub, idx) => (
                                                        <div key={idx} className="criteria-row">
                                                            <span
                                                                className="criteria-name">{getLocalizedField(sub, 'name')}</span>
                                                            <div className="criteria-weight-bar">
                                                                <div
                                                                    className="criteria-bar-fill criteria-bar-technical"
                                                                    style={{width: `${(sub.weight_pct / tender.evaluation_criteria.technical.weight_pct) * 100}%`}}/>
                                                            </div>
                                                            <span
                                                                className="criteria-weight-label">{sub.weight_pct}%</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                    {tender.evaluation_criteria.financial && (
                                        <div className="criteria-block">
                                            <div className="criteria-block-header">
                                                <span
                                                    className="criteria-block-title">{t('tenderDetail.financialCriteria')}</span>
                                                <span
                                                    className="criteria-total-weight">{tender.evaluation_criteria.financial.weight_pct}%</span>
                                            </div>
                                            {tender.evaluation_criteria.financial.subcriteria && tender.evaluation_criteria.financial.subcriteria.length > 0 && (
                                                <div className="criteria-subcriteria">
                                                    {tender.evaluation_criteria.financial.subcriteria.map((sub, idx) => (
                                                        <div key={idx} className="criteria-row">
                                                            <span
                                                                className="criteria-name">{getLocalizedField(sub, 'name')}</span>
                                                            <div className="criteria-weight-bar">
                                                                <div
                                                                    className="criteria-bar-fill criteria-bar-financial"
                                                                    style={{width: `${(sub.weight_pct / tender.evaluation_criteria.financial.weight_pct) * 100}%`}}/>
                                                            </div>
                                                            <span
                                                                className="criteria-weight-label">{sub.weight_pct}%</span>
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </div>
                                    )}
                                </div>
                            </div>
                        )}
                    </Card>

                    {isOwner && bids.length > 0 && (
                        <Card className="bids-card neon-card">
                            <h2 className="section-title">{t('tenderDetail.submittedBids')} ({bids.length})</h2>
                            <div className="bids-list">
                                {bids.map((bid) => (
                                    <div key={bid.id} className="bid-item" data-testid={`bid-${bid.id}`}>
                                        <div className="bid-header">
                                            <div>
                                                <p className="bid-contractor">{bid.contractor_email}</p>
                                                <p className="bid-price">{bid.price.toLocaleString()} {tender.id === '508e1745-94d6-40ca-9bd5-1e09327ad4f8' ? `$` : '₸'}</p>
                                            </div>
                                            <div className="bid-status-info">
                        <span className={`status-badge status-${bid.status}`}>
                          {getStatusLabel(bid.status)}
                        </span>
                                                <span
                                                    className="bid-score">{t('tenderDetail.aiScore')}: {bid.ai_score.toFixed(1)}/100</span>
                                            </div>
                                        </div>
                                        <p className="bid-proposal">{bid.proposal}</p>
                                        <p className="bid-delivery">{t('tenderDetail.delivery')}: {bid.delivery_time}</p>
                                    </div>
                                ))}
                            </div>
                        </Card>
                    )}

                    {tender.status === 'archive' && tender.winner_id == null && (
                        <Card className="neon-card tender-detail-archive-card">
                            <div className="tender-detail-archive-inner">
                                <FileText size={40} className="tender-detail-archive-icon"/>
                                <h2 className="tender-detail-archive-title">
                                    {t('tenderDetail.archiveCancelled')}
                                </h2>
                            </div>
                        </Card>
                    )}

                    {tender.status === 'archive' && tender.winner_id != null && (
                        <Card className="neon-card tender-detail-archive-card">
                            <div className="tender-detail-archive-inner">
                                <FileText size={40} className="tender-detail-archive-icon"/>
                                <h2 className="tender-detail-archive-title">
                                    {t('tenderDetail.archive')}
                                </h2>
                            </div>
                        </Card>
                    )}

                    {tender.status === 'cancelled' && (
                        <Card className="neon-card tender-detail-archive-card">
                            <div className="tender-detail-archive-inner">
                                <FileText size={40} className="tender-detail-archive-icon"/>
                                <h2 className="tender-detail-archive-title">
                                    {t('status.cancelled')}
                                </h2>
                            </div>
                        </Card>
                    )}
                </div>
            </div>

        </StaticLayout>
    );
};

export default TenderDetail;
